SELECT rec_id AS id, "ID bản ghi nguồn" AS source_id, "Mã ngân sách" AS code, ("Brand").name AS brand, ("Năm").name AS year, ("Quý ngân sách").name AS quarter, ("Tháng ngân sách").name AS month, "Số tiền TGĐ duyệt" AS amount, "Nội dung chi tiêu" AS content, ("Loại ngân sách").name AS budget_type, ("Loại đề xuất").name AS request_type, "Note" AS note FROM "A03. Ngân sách được duyệt" WHERE ($1 = '' OR ("Brand").name = $1) AND ($2 = '' OR ("Năm").name = $2) AND ($3 = '' OR ("Quý ngân sách").name = $3) AND ($4 = '' OR ("Tháng ngân sách").name = $4) AND ($5 = '' OR "Mã ngân sách" LIKE $5 OR "Nội dung chi tiêu" LIKE $5) ORDER BY rec_id ASC LIMIT 50 OFFSET $6
